 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The three-cell guide at the top defines the vertical middle ray and
    # the horizontal lanes for the two outer colors.
    guide = next((c for c in range(w - 2)
                  if all(out[0][c + k] != 0 for k in range(3))), None)
    if guide is None:
        return out
    left, middle, right = out[0][guide:guide + 3]
    for r in range(1, h):
        out[r][guide + 1] = middle
    # A matching boundary marker connects to its guide color along that row.
    for r in range(1, h):
        if out[r][0] == left:
            for c in range(guide + 1):
                out[r][c] = left
        if out[r][w - 1] == right:
            for c in range(guide + 2, w):
                out[r][c] = right
    return out
